use clap::{CommandFactory, FromArgMatches, Parser};
use regex::bytes::{NoExpand, Regex, RegexBuilder};
use std::borrow::Cow;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

#[derive(Debug, Parser)]
#[command(
    name = "sd",
    display_name = "sd",
    version = "1.0.0",
    long_version = "v1.0.0",
    about = "An intuitive find & replace CLI"
)]
struct Cli {
    #[arg(help = "The regexp or string (if using `-F`) to search for")]
    find: String,

    #[arg(
        help = "What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc",
        long_help = "What to replace each match with. Unless in string mode, you may use captured values like\n$1, $2, etc"
    )]
    replace_with: String,

    #[arg(
        value_name = "FILES",
        help = "The path to file(s). This is optional - sd can also read from STDIN",
        long_help = "The path to file(s). This is optional - sd can also read from STDIN.\n\nNote: sd modifies files in-place by default. See documentation for examples."
    )]
    files: Vec<PathBuf>,

    #[arg(
        short,
        long,
        help = "Display changes in a human reviewable format (the specifics of the format are likely to change in the future)"
    )]
    preview: bool,

    #[arg(short = 'F', long, help = "Treat FIND and REPLACE_WITH args as literal strings")]
    fixed_strings: bool,

    #[arg(
        short,
        long,
        value_name = "LIMIT",
        default_value_t = 0usize,
        help = "Limit the number of replacements that can occur per file. 0 indicates unlimited replacements"
    )]
    max_replacements: usize,

    #[arg(
        short,
        long,
        value_name = "FLAGS",
        long_help = "Regex flags. May be combined (like `-f mc`).\n\nc - case-sensitive\n\ne - disable multi-line matching\n\ni - case-insensitive\n\nm - multi-line matching\n\ns - make `.` match newlines\n\nw - match full words only",
        help = "Regex flags. May be combined (like `-f mc`)."
    )]
    flags: Option<String>,
}

#[derive(Clone, Copy, Debug)]
struct RegexFlags {
    case_insensitive: bool,
    multi_line: bool,
    dot_matches_new_line: bool,
    word_boundary: bool,
}

#[derive(Debug)]
struct FileInput {
    path: PathBuf,
    contents: Vec<u8>,
}

fn main() -> ExitCode {
    match try_main() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("error: {err}");
            ExitCode::from(1)
        }
    }
}

fn try_main() -> Result<(), String> {
    let bin_name = std::env::args_os()
        .next()
        .as_deref()
        .and_then(Path::new().file_name())
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| String::from("executable"));

    let mut command = Cli::command().bin_name(bin_name);
    let matches = command.get_matches();
    let cli = Cli::from_arg_matches(&matches).expect("validated by clap");

    let regex = build_regex(&cli)?;

    if cli.files.is_empty() {
        let mut stdin = Vec::new();
        io::stdin()
            .read_to_end(&mut stdin)
            .map_err(|err| err.to_string())?;
        let replaced = replace_bytes(&regex, &stdin, &cli);
        io::stdout()
            .write_all(replaced.as_ref())
            .map_err(|err| err.to_string())?;
        return Ok(());
    }

    let inputs = load_files(&cli.files)?;
    if cli.preview {
        write_preview(&inputs, &regex, &cli)?;
    } else {
        write_files(&inputs, &regex, &cli)?;
    }

    Ok(())
}

fn build_regex(cli: &Cli) -> Result<Regex, String> {
    let flags = parse_flags(cli.flags.as_deref().unwrap_or_default());
    let base_pattern = if cli.fixed_strings {
        regex::escape(&cli.find)
    } else {
        cli.find.clone()
    };
    let pattern = if flags.word_boundary {
        format!(r"\b(?:{base_pattern})\b")
    } else {
        base_pattern
    };

    let mut builder = RegexBuilder::new(&pattern);
    builder.case_insensitive(flags.case_insensitive);
    builder.multi_line(flags.multi_line);
    builder.dot_matches_new_line(flags.dot_matches_new_line);

    builder
        .build()
        .map_err(|err| format!("invalid regex {err}"))
}

fn parse_flags(raw: &str) -> RegexFlags {
    let mut case_insensitive = false;
    let mut word_boundary = false;
    let mut dot_matches_new_line = false;

    for flag in raw.chars() {
        match flag {
            'c' => case_insensitive = false,
            'i' => case_insensitive = true,
            's' => dot_matches_new_line = true,
            'w' => word_boundary = true,
            _ => {}
        }
    }

    RegexFlags {
        case_insensitive,
        multi_line: !raw.contains('e'),
        dot_matches_new_line,
        word_boundary,
    }
}

fn load_files(files: &[PathBuf]) -> Result<Vec<FileInput>, String> {
    for path in files {
        if !path.exists() {
            return Err(format!("invalid path: {}", path.display()));
        }
    }

    let mut inputs = Vec::with_capacity(files.len());
    for path in files {
        if path.is_dir() {
            return Err(io::Error::from_raw_os_error(19).to_string());
        }

        let contents = fs::read(path).map_err(|err| err.to_string())?;
        inputs.push(FileInput {
            path: path.clone(),
            contents,
        });
    }

    Ok(inputs)
}

fn replace_bytes<'a>(regex: &Regex, input: &'a [u8], cli: &Cli) -> Cow<'a, [u8]> {
    if cli.fixed_strings {
        let replacer = NoExpand(cli.replace_with.as_bytes());
        if cli.max_replacements == 0 {
            regex.replace_all(input, replacer)
        } else {
            regex.replacen(input, cli.max_replacements, replacer)
        }
    } else if cli.max_replacements == 0 {
        regex.replace_all(input, cli.replace_with.as_bytes())
    } else {
        regex.replacen(input, cli.max_replacements, cli.replace_with.as_bytes())
    }
}

fn write_preview(inputs: &[FileInput], regex: &Regex, cli: &Cli) -> Result<(), String> {
    let mut stdout = io::stdout().lock();
    let show_headers = inputs.len() > 1;

    for input in inputs {
        if show_headers {
            writeln!(stdout, "----- FILE {} -----", input.path.display()).map_err(io_to_string)?;
        }

        let replaced = replace_bytes(regex, &input.contents, cli);
        stdout.write_all(replaced.as_ref()).map_err(io_to_string)?;
    }

    Ok(())
}

fn write_files(inputs: &[FileInput], regex: &Regex, cli: &Cli) -> Result<(), String> {
    for input in inputs {
        let replaced = replace_bytes(regex, &input.contents, cli);
        fs::write(&input.path, replaced.as_ref()).map_err(|err| err.to_string())?;
    }

    Ok(())
}

fn io_to_string(err: io::Error) -> String {
    err.to_string()
}

