+const versionOutput = "sd 1.0.0\n"
+
+type cliOptions struct {
+	find            string
+	replaceWith     string
+	files           []string
+	preview         bool
+	fixedStrings    bool
+	maxReplacements int
+	flags           string
+
+	previewSet      bool
+	fixedStringsSet bool
+	maxSet          bool
+	flagsSet        bool
