+
+func normalizeNumericEscapes(pattern string) string {
+	var out strings.Builder
+	backslashes := 0
+
+	flushBackslashes := func(next byte) {
+		count := backslashes
+		if next >= '0' && next <= '9' && count%2 == 1 {
+			count++
+		}
+		out.WriteString(strings.Repeat("\\", count))
+		backslashes = 0
+	}
+
+	for i := 0; i < len(pattern); i++ {
+		if pattern[i] == '\\' {
+			backslashes++
+			continue
+		}
+		if backslashes > 0 {
+			flushBackslashes(pattern[i])
+		}
+		out.WriteByte(pattern[i])
+	}
+	if backslashes > 0 {
+		out.WriteString(strings.Repeat("\\", backslashes))
+	}
+	return out.String()
+}
+
+func normalizeRegexpError(err error) string {
+	msg := err.Error()
+	if strings.HasPrefix(msg, "error parsing regexp: ") {
+		return strings.TrimPrefix(msg, "error parsing regexp: ")
+	}
+	return msg
+}
+
+func formatOSError(err error) string {
+	var pathErr *os.PathError
+	if errors.As(err, &pathErr) {
+		if errno, ok := pathErr.Err.(syscall.Errno); ok {
+			return fmt.Sprintf("%s (os error %d)", capitalize(errno.Error()), int(errno))
+		}
+		return capitalize(pathErr.Err.Error())
+	}
+
+	var errno syscall.Errno
+	if errors.As(err, &errno) {
+		return fmt.Sprintf("%s (os error %d)", capitalize(errno.Error()), int(errno))
+	}
+
+	return capitalize(err.Error())
+}
+
+func capitalize(s string) string {
+	if s == "" {
+		return s
+	}
+	r, size := utf8.DecodeRuneInString(s)
+	if r == utf8.RuneError && size == 0 {
+		return s
+	}
+	return string(unicode.ToUpper(r)) + s[size:]
+}
+
+func duplicateArgumentError(binName, argument string) error {
+	return fmt.Errorf("error: the argument '%s' cannot be used multiple times\n\nUsage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n", argument, binName)
+}
+
+func missingValueError(argument string) error {
+	return fmt.Errorf("error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n", argument)
+}
+
+func invalidMaxReplacementsError(value string) error {
+	return fmt.Errorf("error: invalid value '%s' for '--max-replacements <LIMIT>': invalid digit found in string\n\nFor more information, try '--help'.\n", value)
+}
+
+func unexpectedArgumentError(binName, argument string) error {
+	return fmt.Errorf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n", argument, argument, argument, binName)
+}
+
+func missingRequiredArgsError(binName string, opts cliOptions, count int) error {
+	var missing []string
+	if count == 0 {
+		missing = append(missing, "  <FIND>", "  <REPLACE_WITH>")
+	} else {
+		missing = append(missing, "  <REPLACE_WITH>")
+	}
