use std::borrow::Cow;
use std::env;
use std::ffi::OsStr;
use std::fs::{self, File, Permissions};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process;

use clap::{value_parser, Arg, ArgAction, Command};
use memmap2::MmapOptions;
use regex::bytes::{NoExpand, Regex, RegexBuilder};
use tempfile::NamedTempFile;

const APP_NAME: &str = "sd";
const APP_VERSION: &str = "1.0.0";
const ABOUT: &str = "An intuitive find & replace CLI";

#[derive(Debug)]
struct Cli {
    preview: bool,
    fixed_strings: bool,
    max_replacements: usize,
    flags: String,
    find: String,
    replace_with: String,
    files: Vec<PathBuf>,
}

#[derive(Debug)]
enum AppError {
    InvalidPath(PathBuf),
    InvalidRegex(regex::Error),
    Io(io::Error),
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidPath(path) => write!(f, "invalid path: {}", path.display()),
            Self::InvalidRegex(err) => write!(f, "invalid regex {}", err),
            Self::Io(err) => write!(f, "{err}"),
        }
    }
}

impl std::error::Error for AppError {}

impl From<io::Error> for AppError {
    fn from(err: io::Error) -> Self {
        Self::Io(err)
    }
}

#[derive(Debug)]
struct PreparedFile {
    display_path: PathBuf,
    target_path: PathBuf,
    permissions: Permissions,
    contents: Vec<u8>,
}

fn main() {
    if let Err(err) = run() {
        eprintln!("error: {err}");
        process::exit(1);
    }
}

fn run() -> Result<(), AppError> {
    let cli = parse_cli();
    let regex = build_regex(&cli.find, &cli.flags, cli.fixed_strings)?;

    if cli.files.is_empty() {
        let mut input = Vec::new();
        io::stdin().read_to_end(&mut input)?;
        let output = replace_all(&regex, &input, &cli.replace_with, cli.max_replacements, cli.fixed_strings);
        io::stdout().write_all(&output)?;
        return Ok(());
    }

    let mut prepared = Vec::with_capacity(cli.files.len());
    for path in &cli.files {
        prepared.push(prepare_file(path, &regex, &cli.replace_with, cli.max_replacements, cli.fixed_strings)?);
    }

    if cli.preview {
        write_preview(&prepared)?;
    } else {
        for file in &prepared {
            write_file(file)?;
        }
    }

    Ok(())
}

fn parse_cli() -> Cli {
    let args: Vec<_> = env::args_os().collect();
    let bin_name = args
        .first()
        .and_then(|arg| Path::new(arg).file_name())
        .unwrap_or_else(|| OsStr::new("executable"))
        .to_string_lossy()
        .into_owned();

    let matches = command(bin_name)
        .try_get_matches_from(args)
        .unwrap_or_else(|err| err.exit());

    Cli {
        preview: matches.get_flag("preview"),
        fixed_strings: matches.get_flag("fixed-strings"),
        max_replacements: *matches.get_one::<usize>("max-replacements").unwrap_or(&0),
        flags: matches
            .get_one::<String>("flags")
            .cloned()
            .unwrap_or_default(),
        find: matches
            .get_one::<String>("find")
            .expect("required by clap")
            .clone(),
        replace_with: matches
            .get_one::<String>("replace-with")
            .expect("required by clap")
            .clone(),
        files: matches
            .get_many::<PathBuf>("files")
            .into_iter()
            .flatten()
            .cloned()
            .collect(),
    }
}

fn command(bin_name: String) -> Command {
    Command::new(APP_NAME)
        .version(APP_VERSION)
        .about(ABOUT)
        .long_about(ABOUT)
        .bin_name(bin_name)
        .arg(
            Arg::new("preview")
                .short('p')
                .long("preview")
                .action(ArgAction::SetTrue)
                .help("Display changes in a human reviewable format (the specifics of the format are likely to change in the future)")
                .long_help("Display changes in a human reviewable format (the specifics of the format are likely to change in the future)"),
        )
        .arg(
            Arg::new("fixed-strings")
                .short('F')
                .long("fixed-strings")
                .action(ArgAction::SetTrue)
                .help("Treat FIND and REPLACE_WITH args as literal strings")
                .long_help("Treat FIND and REPLACE_WITH args as literal strings"),
        )
        .arg(
            Arg::new("max-replacements")
                .short('n')
                .long("max-replacements")
                .value_name("LIMIT")
                .value_parser(value_parser!(usize))
                .default_value("0")
                .help("Limit the number of replacements that can occur per file. 0 indicates unlimited replacements")
                .long_help("Limit the number of replacements that can occur per file. 0 indicates unlimited replacements"),
        )
        .arg(
            Arg::new("flags")
                .short('f')
                .long("flags")
                .value_name("FLAGS")
                .help("Regex flags. May be combined (like `-f mc`).")
                .long_help(
                    "Regex flags. May be combined (like `-f mc`).\n\nc - case-sensitive\n\ne - disable multi-line matching\n\ni - case-insensitive\n\nm - multi-line matching\n\ns - make `.` match newlines\n\nw - match full words only",
                ),
        )
        .arg(
            Arg::new("find")
                .value_name("FIND")
                .required(true)
                .help("The regexp or string (if using `-F`) to search for")
                .long_help("The regexp or string (if using `-F`) to search for"),
        )
        .arg(
            Arg::new("replace-with")
                .value_name("REPLACE_WITH")
                .required(true)
                .help("What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc")
                .long_help("What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc"),
        )
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .num_args(0..)
                .value_parser(value_parser!(PathBuf))
                .help("The path to file(s). This is optional - sd can also read from STDIN")
                .long_help("The path to file(s). This is optional - sd can also read from STDIN.\n\nNote: sd modifies files in-place by default. See documentation for examples."),
        )
}

fn build_regex(find: &str, flags: &str, fixed_strings: bool) -> Result<Regex, AppError> {
    let mut pattern = if fixed_strings {
        regex::escape(find)
    } else {
        find.to_owned()
    };

    if flags.contains('w') {
        pattern = format!(r"\b(?:{})\b", pattern);
    }

    let mut builder = RegexBuilder::new(&pattern);
    builder.case_insensitive(false);
    builder.dot_matches_new_line(false);
    builder.multi_line(true);
    builder.unicode(true);

    for flag in flags.chars() {
        match flag {
            'c' => {
                builder.case_insensitive(false);
            }
            'i' => {
                builder.case_insensitive(true);
            }
            's' => {
                builder.dot_matches_new_line(true);
            }
            _ => {}
        }
    }

    if flags.contains('e') {
        builder.multi_line(false);
    }

    builder.build().map_err(AppError::InvalidRegex)
}

fn replace_all(
    regex: &Regex,
    input: &[u8],
    replace_with: &str,
    max_replacements: usize,
    fixed_strings: bool,
) -> Vec<u8> {
    let output: Cow<'_, [u8]> = if fixed_strings {
        if max_replacements == 0 {
            regex.replace_all(input, NoExpand(replace_with.as_bytes()))
        } else {
            regex.replacen(input, max_replacements, NoExpand(replace_with.as_bytes()))
        }
    } else if max_replacements == 0 {
        regex.replace_all(input, replace_with.as_bytes())
    } else {
        regex.replacen(input, max_replacements, replace_with.as_bytes())
    };

    output.into_owned()
}

fn prepare_file(
    display_path: &Path,
    regex: &Regex,
    replace_with: &str,
    max_replacements: usize,
    fixed_strings: bool,
) -> Result<PreparedFile, AppError> {
    let target_path = resolve_target_path(display_path)?;
    let file = File::open(&target_path).map_err(map_path_error(display_path))?;
    let permissions = file.metadata()?.permissions();
    let mmap = unsafe { MmapOptions::new().map(&file)? };
    let contents = replace_all(regex, &mmap, replace_with, max_replacements, fixed_strings);

    Ok(PreparedFile {
        display_path: display_path.to_path_buf(),
        target_path,
        permissions,
        contents,
    })
}

fn resolve_target_path(path: &Path) -> Result<PathBuf, AppError> {
    match path.canonicalize() {
        Ok(path) => Ok(path),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Err(AppError::InvalidPath(path.to_path_buf())),
        Err(err) => Err(AppError::Io(err)),
    }
}

fn map_path_error(display_path: &Path) -> impl FnOnce(io::Error) -> AppError + '_ {
    move |err| {
        if err.kind() == io::ErrorKind::NotFound {
            AppError::InvalidPath(display_path.to_path_buf())
        } else {
            AppError::Io(err)
        }
    }
}

fn write_preview(files: &[PreparedFile]) -> Result<(), AppError> {
    let mut stdout = io::stdout().lock();

    if files.len() == 1 {
        stdout.write_all(&files[0].contents)?;
        return Ok(());
    }

    for file in files {
        stdout.write_all(b"----- FILE ")?;
        stdout.write_all(path_bytes(&file.display_path).as_ref())?;
        stdout.write_all(b" -----\n")?;
        stdout.write_all(&file.contents)?;
    }

    Ok(())
}

fn write_file(file: &PreparedFile) -> Result<(), AppError> {
    let parent = file
        .target_path
        .parent()
        .unwrap_or_else(|| Path::new("."));
    let mut temp = NamedTempFile::new_in(parent)?;
    temp.write_all(&file.contents)?;
    temp.flush()?;
    fs::set_permissions(temp.path(), file.permissions.clone())?;
    temp.persist(&file.target_path)
        .map_err(|err| AppError::Io(err.error))?;
    Ok(())
}

#[cfg(unix)]
fn path_bytes(path: &Path) -> Cow<'_, [u8]> {
    use std::os::unix::ffi::OsStrExt;

    Cow::Borrowed(path.as_os_str().as_bytes())
}

#[cfg(not(unix))]
fn path_bytes(path: &Path) -> Cow<'_, [u8]> {
    Cow::Owned(path.to_string_lossy().into_owned().into_bytes())
}

